<script setup lang="ts">import VSkeletonLayout from '../feedback/VSkeletonLayout.vue';import {watch,nextTick,ref} from 'vue';const p=defineProps<{open:boolean;title:string;loading?:boolean;loadingLabel?:string}>();const emit=defineEmits<{close:[]}>();const modal=ref<HTMLElement|null>(null);let prev:HTMLElement|null=null;watch(()=>p.open,async v=>{if(v){prev=document.activeElement as HTMLElement;await nextTick();modal.value?.focus()}else prev?.focus()},{immediate:true});function onKey(e:KeyboardEvent){if(e.key==='Escape')emit('close');if(e.key==='Tab'&&modal.value){const a=Array.from(modal.value.querySelectorAll<HTMLElement>('button,input,select,textarea,a[href]')).filter(x=>!x.hasAttribute('disabled'));if(!a.length){e.preventDefault();return}if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a[a.length-1].focus()}else if(!e.shiftKey&&document.activeElement===a[a.length-1]){e.preventDefault();a[0].focus()}}}</script><template><Teleport to="body"><div v-if="open" class="vx-overlay" @keydown="onKey"><div class="vx-overlay__backdrop" @click="emit('close')"/><section ref="modal" tabindex="-1" role="dialog" aria-modal="true" :aria-label="title" class="vx-modal"><header><h2>{{title}}</h2><button aria-label="Close" @click="emit('close')">×</button></header><div :aria-busy="loading || undefined"><VSkeletonLayout v-if="loading" variant="form" :label="loadingLabel || 'Loading…'"/><slot v-else/></div><footer v-if="$slots.footer && !loading"><slot name="footer"/></footer></section></div></Teleport></template>